// Determine if we have an active conversation or need to create one
const item = $input.first();
const conversations = Array.isArray(item.json) ? item.json : (item.json.data || [item.json]);
const customerInfo = $('Extract Customer Info').first().json;

let conversation = null;
let needsCreation = true;
let isPaused = false;

if (conversations.length > 0 && conversations[0].id) {
  conversation = conversations[0];
  needsCreation = false;
  isPaused = conversation.status === 'paused_for_handover';
}

return [{
  json: {
    ...customerInfo,
    conversationId: conversation?.id || '',
    conversationStatus: conversation?.status || 'new',
    conversationContext: conversation?.context || {},
    needsCreation: needsCreation,
    isPaused: isPaused
  }
}];

// Notify that conversation is paused - staff is handling
const item = $input.first();
return [{
  json: {
    action: 'send_paused_notice',
    recipientWaId: item.json.senderWaId,
    phoneNumberId: item.json.phoneNumberId,
    message: item.json.preferredLanguage === 'ta' 
      ? 'உங்கள் உரையாடலை எங்கள் குழு கையாளுகிறது. விரைவில் பதிலளிப்பார்கள்.'
      : item.json.preferredLanguage === 'si'
      ? 'ඔබේ සංවාදය අපේ කණ්ඩායම විසින් හසුරුවනු ලැබේ. ඔවුන් ඉක්මනින් ප්‍රතිචාර දක්වනු ඇත.'
      : 'Your conversation is being handled by our team. They will respond shortly.',
    conversationId: item.json.conversationId,
    customerId: item.json.customerId
  }
}];

// Create new conversation if needed, then fetch message history
const item = $input.first();
const supabaseUrl = $env.SUPABASE_URL;
const serviceKey = $env.SUPABASE_SERVICE_ROLE_KEY;

let conversationId = item.json.conversationId;

// Create conversation if needed
if (item.json.needsCreation) {
  const createResp = await fetch(`${supabaseUrl}/rest/v1/conversations`, {
    method: 'POST',
    headers: {
      'apikey': serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: JSON.stringify({
      customer_id: item.json.customerId,
      status: 'active',
      language: item.json.preferredLanguage || 'en',
      context: {},
      started_at: new Date().toISOString(),
      last_message_at: new Date().toISOString()
    })
  });
  const created = await createResp.json();
  conversationId = Array.isArray(created) ? created[0]?.id : created.id;
}

// Fetch recent message history
const historyResp = await fetch(
  `${supabaseUrl}/rest/v1/messages?conversation_id=eq.${conversationId}&order=created_at.desc&limit=10`,
  {
    headers: {
      'apikey': serviceKey,
      'Authorization': `Bearer ${serviceKey}`
    }
  }
);
const history = await historyResp.json();

return [{
  json: {
    ...item.json,
    conversationId: conversationId,
    messageHistory: Array.isArray(history) ? history.reverse() : []
  }
}];

// Build the full AI context: system prompt, conversation history, tools
const item = $input.first();
const shopName = $env.SHOP_NAME || 'Fashion House';
const currency = $env.SHOP_CURRENCY || 'LKR';

const systemPrompt = `You are a friendly and professional sales assistant for ${shopName}, a clothing shop in Sri Lanka.

IMPORTANT RULES:
- You MUST respond in the same language the customer uses. You support English, Tamil (தமிழ்), and Sinhala (සිංහල).
- NEVER invent products, prices, stock levels, discounts, delivery promises, or order statuses. Use ONLY data from your tools.
- NEVER claim an order is confirmed unless the create_order tool succeeds.
- NEVER change prices or issue refunds without human authorization.
- NEVER request payment card details, OTPs, or passwords.
- Keep customer information private.
- Use concise WhatsApp-friendly replies. Avoid long paragraphs.
- Use emojis sparingly for a warm tone.

YOUR CAPABILITIES:
1. Help customers browse and search for clothing (use search_products tool)
2. Provide product details, prices in ${currency}, sizes, colours, and images
3. Recommend products based on budget, category, size, colour, style, occasion
4. Help customers add items to their cart and manage it
5. Collect order details (name, address, contact, payment method)
6. Create orders with explicit customer confirmation
7. Check order status
8. Answer questions about delivery, payment, exchange, and return policies
9. Escalate to human staff when needed

ORDER FLOW:
1. Help customer find products
2. Add to cart when they decide
3. When ready to order, collect: name, delivery address, contact number, payment method
4. Show order summary with itemized list and total in ${currency}
5. Ask for explicit confirmation ("Yes, place my order")
6. Only then call create_order
7. Share the order reference number

ESCALATE TO HUMAN when:
- Customer requests a refund
- Customer has a complaint
- Customer asks about custom/bulk orders
- Customer requests a discount you cannot authorize
- You cannot resolve the query after 3 attempts
- Customer explicitly asks to speak to a person

Current currency: ${currency}
Shop: ${shopName}`;

// Build conversation messages from history
const messages = [];
const history = item.json.messageHistory || [];

for (const msg of history) {
  if (msg.direction === 'inbound') {
    messages.push({ role: 'user', content: msg.content || '' });
  } else if (msg.direction === 'outbound' && msg.message_type !== 'system') {
    messages.push({ role: 'assistant', content: msg.content || '' });
  }
}

// Add current message
messages.push({ role: 'user', content: item.json.messageBody });

// Define tools for the AI
const tools = [
  {
    name: 'search_products',
    description: 'Search the product catalog. Returns products matching the criteria with name, price, sizes, colours, and image URLs.',
    input_schema: {
      type: 'object',
      properties: {
        category: { type: 'string', description: 'Product category: t-shirts, shirts, trousers, jeans, dresses, sarees, kidswear, sportswear, accessories' },
        min_price: { type: 'number', description: 'Minimum price in LKR' },
        max_price: { type: 'number', description: 'Maximum price in LKR' },
        size: { type: 'string', description: 'Size: XS, S, M, L, XL, XXL, or specific sizes' },
        colour: { type: 'string', description: 'Colour name' },
        gender: { type: 'string', description: 'Target: men, women, unisex, kids' },
        keyword: { type: 'string', description: 'Search keyword for name or description' }
      }
    }
  },
  {
    name: 'get_product_details',
    description: 'Get full details of a specific product including all variants, sizes, colours, and stock.',
    input_schema: {
      type: 'object',
      properties: {
        product_id: { type: 'string', description: 'The product UUID' }
      },
      required: ['product_id']
    }
  },
  {
    name: 'check_stock',
    description: 'Check if a specific product variant (size + colour) is in stock.',
    input_schema: {
      type: 'object',
      properties: {
        variant_id: { type: 'string', description: 'The variant UUID' }
      },
      required: ['variant_id']
    }
  },
  {
    name: 'add_to_cart',
    description: 'Add a product variant to the customer cart.',
    input_schema: {
      type: 'object',
      properties: {
        variant_id: { type: 'string', description: 'The variant UUID to add' },
        quantity: { type: 'integer', description: 'Quantity to add', default: 1 }
      },
      required: ['variant_id']
    }
  },
  {
    name: 'get_cart',
    description: 'Get the current contents of the customer cart with item details and totals.',
    input_schema: {
      type: 'object',
      properties: {}
    }
  },
  {
    name: 'create_order',
    description: 'Create an order from the cart. Only call AFTER the customer explicitly confirms. Returns order reference.',
    input_schema: {
      type: 'object',
      properties: {
        customer_name: { type: 'string', description: 'Customer full name' },
        delivery_address: { type: 'string', description: 'Full delivery address' },
        contact_number: { type: 'string', description: 'Contact phone number' },
        payment_method: { type: 'string', description: 'Payment method: cod (Cash on Delivery) or bank_transfer' }
      },
      required: ['customer_name', 'delivery_address', 'contact_number', 'payment_method']
    }
  },
  {
    name: 'get_order_status',
    description: 'Get the status and details of an order by order reference number.',
    input_schema: {
      type: 'object',
      properties: {
        order_ref: { type: 'string', description: 'Order reference like CLT-2026-000001' }
      },
      required: ['order_ref']
    }
  },
  {
    name: 'get_shop_policies',
    description: 'Get shop policies: delivery, payment methods, returns, exchanges.',
    input_schema: {
      type: 'object',
      properties: {
        policy_type: { type: 'string', description: 'Policy type: delivery, payment, returns, exchange, all' }
      },
      required: ['policy_type']
    }
  },
  {
    name: 'request_human_handover',
    description: 'Transfer the conversation to a human staff member. Use when the customer needs help beyond AI capabilities.',
    input_schema: {
      type: 'object',
      properties: {
        reason: { type: 'string', description: 'Why the handover is needed' },
        priority: { type: 'string', enum: ['low', 'medium', 'high', 'urgent'], description: 'Priority level' }
      },
      required: ['reason']
    }
  }
];

return [{
  json: {
    ...item.json,
    systemPrompt: systemPrompt,
    messages: messages,
    tools: tools,
    toolCallCount: 0,
    maxToolCalls: parseInt($env.AI_TOOL_CALL_LIMIT || '5')
  }
}];

// Process the AI response - handle text and tool_use responses
const item = $input.first();
const aiResponse = item.json;
const context = $('Build AI Context').first().json;

// Check for API errors
if (aiResponse.error || !aiResponse.content) {
  const fallback = $env.AI_FALLBACK_RESPONSE || "I'm sorry, I'm having trouble right now. Please try again shortly or type 'help' to speak with our team.";
  return [{
    json: {
      responseType: 'text',
      responseText: fallback,
      isError: true,
      ...context
    }
  }];
}

const content = aiResponse.content || [];
const stopReason = aiResponse.stop_reason;

// Check if AI wants to use a tool
if (stopReason === 'tool_use') {
  const toolUseBlocks = content.filter(b => b.type === 'tool_use');
  const textBlocks = content.filter(b => b.type === 'text');

  if (toolUseBlocks.length > 0 && context.toolCallCount < context.maxToolCalls) {
    const toolCall = toolUseBlocks[0];
    return [{
      json: {
        responseType: 'tool_use',
        toolName: toolCall.name,
        toolInput: toolCall.input || {},
        toolUseId: toolCall.id,
        prefixText: textBlocks.map(b => b.text).join('\n'),
        toolCallCount: context.toolCallCount + 1,
        ...context
      }
    }];
  }
}

// Extract text response
const textContent = content
  .filter(b => b.type === 'text')
  .map(b => b.text)
  .join('\n');

return [{
  json: {
    responseType: 'text',
    responseText: textContent || "I'm here to help! What are you looking for today?",
    isError: false,
    ...context
  }
}];

// Execute the tool call against Supabase and return the result
const item = $input.first();
const toolName = item.json.toolName;
const toolInput = item.json.toolInput;
const supabaseUrl = $env.SUPABASE_URL;
const serviceKey = $env.SUPABASE_SERVICE_ROLE_KEY;
const customerId = item.json.customerId;

const headers = {
  'apikey': serviceKey,
  'Authorization': `Bearer ${serviceKey}`,
  'Content-Type': 'application/json'
};

let toolResult = { error: 'Unknown tool' };

try {
  switch (toolName) {
    case 'search_products': {
      const resp = await fetch(`${supabaseUrl}/rest/v1/rpc/search_products`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          p_category: toolInput.category || null,
          p_min_price: toolInput.min_price || null,
          p_max_price: toolInput.max_price || null,
          p_size: toolInput.size || null,
          p_colour: toolInput.colour || null,
          p_gender: toolInput.gender || null,
          p_keyword: toolInput.keyword || null,
          p_limit: 5
        })
      });
      toolResult = await resp.json();
      break;
    }
    case 'get_product_details': {
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/products?id=eq.${toolInput.product_id}&select=*,product_variants(*)`,
        { headers }
      );
      const products = await resp.json();
      toolResult = products.length > 0 ? products[0] : { error: 'Product not found' };
      break;
    }
    case 'check_stock': {
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/product_variants?id=eq.${toolInput.variant_id}&select=*,products(name,base_price,sale_price)`,
        { headers }
      );
      const variants = await resp.json();
      if (variants.length > 0) {
        const v = variants[0];
        toolResult = {
          variant_id: v.id,
          size: v.size,
          colour: v.colour,
          available: v.available_quantity - v.reserved_quantity,
          in_stock: (v.available_quantity - v.reserved_quantity) > 0,
          product_name: v.products?.name
        };
      } else {
        toolResult = { error: 'Variant not found' };
      }
      break;
    }
    case 'add_to_cart': {
      const resp = await fetch(`${supabaseUrl}/rest/v1/rpc/add_to_cart`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          p_customer_id: customerId,
          p_variant_id: toolInput.variant_id,
          p_quantity: toolInput.quantity || 1
        })
      });
      toolResult = await resp.json();
      break;
    }
    case 'get_cart': {
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/carts?customer_id=eq.${customerId}&status=eq.active&select=*,cart_items(*,products(name,image_urls),product_variants(size,colour))`,
        { headers }
      );
      const carts = await resp.json();
      toolResult = carts.length > 0 ? carts[0] : { items: [], message: 'Cart is empty' };
      break;
    }
    case 'create_order': {
      const resp = await fetch(`${supabaseUrl}/rest/v1/rpc/place_order`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          p_customer_id: customerId,
          p_customer_name: toolInput.customer_name,
          p_delivery_address: toolInput.delivery_address,
          p_contact_number: toolInput.contact_number,
          p_payment_method: toolInput.payment_method
        })
      });
      toolResult = await resp.json();
      break;
    }
    case 'get_order_status': {
      const resp = await fetch(
        `${supabaseUrl}/rest/v1/orders?order_ref=eq.${toolInput.order_ref}&customer_id=eq.${customerId}&select=*,order_items(*)`,
        { headers }
      );
      const orders = await resp.json();
      toolResult = orders.length > 0 ? orders[0] : { error: 'Order not found' };
      break;
    }
    case 'get_shop_policies': {
      const policyType = toolInput.policy_type || 'all';
      let query = `${supabaseUrl}/rest/v1/shop_settings`;
      if (policyType !== 'all') {
        query += `?key=like.policy_${policyType}*`;
      } else {
        query += '?key=like.policy_*';
      }
      const resp = await fetch(query, { headers });
      toolResult = await resp.json();
      break;
    }
    case 'request_human_handover': {
      // Create handover request
      const resp = await fetch(`${supabaseUrl}/rest/v1/handover_requests`, {
        method: 'POST',
        headers: { ...headers, 'Prefer': 'return=representation' },
        body: JSON.stringify({
          conversation_id: item.json.conversationId,
          customer_id: customerId,
          reason: toolInput.reason,
          priority: toolInput.priority || 'medium',
          status: 'pending'
        })
      });
      // Pause the conversation
      await fetch(`${supabaseUrl}/rest/v1/conversations?id=eq.${item.json.conversationId}`, {
        method: 'PATCH',
        headers,
        body: JSON.stringify({ status: 'paused_for_handover' })
      });
      toolResult = { success: true, message: 'Handover requested. A team member will assist shortly.' };
      break;
    }
  }
} catch (err) {
  toolResult = { error: `Tool execution failed: ${err.message}` };
}

// Build updated messages with tool result for next AI call
const updatedMessages = [...item.json.messages];

// Add the assistant's tool_use message
updatedMessages.push({
  role: 'assistant',
  content: [
    ...(item.json.prefixText ? [{ type: 'text', text: item.json.prefixText }] : []),
    {
      type: 'tool_use',
      id: item.json.toolUseId,
      name: toolName,
      input: toolInput
    }
  ]
});

// Add the tool result
updatedMessages.push({
  role: 'user',
  content: [
    {
      type: 'tool_result',
      tool_use_id: item.json.toolUseId,
      content: JSON.stringify(toolResult).substring(0, 4000)
    }
  ]
});

return [{
  json: {
    ...item.json,
    messages: updatedMessages,
    lastToolResult: toolResult,
    toolCallCount: item.json.toolCallCount
  }
}];

// Process the follow-up AI response after tool execution
const item = $input.first();
const aiResponse = item.json;
const context = $('Execute Tool Call').first().json;

// Check for API errors
if (aiResponse.error || !aiResponse.content) {
  const fallback = $env.AI_FALLBACK_RESPONSE || "I'm sorry, I'm having trouble right now. Please try again shortly or type 'help' to speak with our team.";
  return [{
    json: {
      responseType: 'text',
      responseText: fallback,
      isError: true,
      ...context
    }
  }];
}

const content = aiResponse.content || [];
const stopReason = aiResponse.stop_reason;

// If AI wants another tool call and we haven't hit the limit
if (stopReason === 'tool_use' && context.toolCallCount < context.maxToolCalls) {
  const toolUseBlocks = content.filter(b => b.type === 'tool_use');
  const textBlocks = content.filter(b => b.type === 'text');

  if (toolUseBlocks.length > 0) {
    const toolCall = toolUseBlocks[0];
    // Add this response to messages for the next iteration
    const updatedMessages = [...context.messages];
    updatedMessages.push({
      role: 'assistant',
      content: content
    });

    return [{
      json: {
        responseType: 'tool_use',
        toolName: toolCall.name,
        toolInput: toolCall.input || {},
        toolUseId: toolCall.id,
        prefixText: textBlocks.map(b => b.text).join('\n'),
        messages: updatedMessages,
        toolCallCount: context.toolCallCount + 1,
        ...context,
        messages: updatedMessages
      }
    }];
  }
}

// Extract final text response
const textContent = content
  .filter(b => b.type === 'text')
  .map(b => b.text)
  .join('\n');

return [{
  json: {
    responseType: 'text',
    responseText: textContent || "Is there anything else I can help you with?",
    isError: false,
    ...context
  }
}];

// Format the AI response for WhatsApp - trim, enforce char limits
const item = $input.first();
let text = item.json.responseText || '';

// WhatsApp message limit is ~4096 chars for text messages
const MAX_LENGTH = 4000;
if (text.length > MAX_LENGTH) {
  text = text.substring(0, MAX_LENGTH - 50) + '\n\n... (message trimmed)';
}

// Clean up formatting
text = text.trim();

return [{
  json: {
    formattedResponse: text,
    recipientWaId: item.json.senderWaId,
    phoneNumberId: item.json.phoneNumberId || $env.META_PHONE_NUMBER_ID,
    customerId: item.json.customerId,
    conversationId: item.json.conversationId,
    messageBody: item.json.messageBody,
    whatsappMessageId: item.json.whatsappMessageId
  }
}];

// Save both inbound and outbound messages to Supabase
const item = $input.first();
const context = $('Format WhatsApp Reply').first().json;
const supabaseUrl = $env.SUPABASE_URL;
const serviceKey = $env.SUPABASE_SERVICE_ROLE_KEY;

const headers = {
  'apikey': serviceKey,
  'Authorization': `Bearer ${serviceKey}`,
  'Content-Type': 'application/json',
  'Prefer': 'return=minimal'
};

// Save inbound message
await fetch(`${supabaseUrl}/rest/v1/messages`, {
  method: 'POST',
  headers,
  body: JSON.stringify({
    conversation_id: context.conversationId,
    customer_id: context.customerId,
    direction: 'inbound',
    message_type: 'text',
    content: context.messageBody,
    whatsapp_message_id: context.whatsappMessageId,
    status: 'received'
  })
});

// Save outbound message
const waResponse = item.json;
const outboundMsgId = waResponse.messages?.[0]?.id || null;

await fetch(`${supabaseUrl}/rest/v1/messages`, {
  method: 'POST',
  headers,
  body: JSON.stringify({
    conversation_id: context.conversationId,
    customer_id: context.customerId,
    direction: 'outbound',
    message_type: 'text',
    content: context.formattedResponse,
    whatsapp_message_id: outboundMsgId,
    status: 'sent'
  })
});

// Update conversation last_message_at
await fetch(`${supabaseUrl}/rest/v1/conversations?id=eq.${context.conversationId}`, {
  method: 'PATCH',
  headers,
  body: JSON.stringify({ last_message_at: new Date().toISOString() })
});

return [{ json: { success: true, conversationId: context.conversationId } }];
